# frozen_string_literal: true

module RuboCop
  module Cop
    module Style
      # If the branch of a conditional consists solely of a conditional node,
      # its conditions can be combined with the conditions of the outer branch.
      # This helps to keep the nesting level from getting too deep.
      #
      # @example
      #   # bad
      #   if condition_a
      #     if condition_b
      #       do_something
      #     end
      #   end
      #
      #   # bad
      #   if condition_b
      #     do_something
      #   end if condition_a
      #
      #   # good
      #   if condition_a && condition_b
      #     do_something
      #   end
      #
      # @example AllowModifier: false (default)
      #   # bad
      #   if condition_a
      #     do_something if condition_b
      #   end
      #
      #   # bad
      #   if condition_b
      #     do_something
      #   end if condition_a
      #
      # @example AllowModifier: true
      #   # good
      #   if condition_a
      #     do_something if condition_b
      #   end
      #
      #   # good
      #   if condition_b
      #     do_something
      #   end if condition_a
      class SoleNestedConditional < Base
        include RangeHelp
        extend AutoCorrector

        MSG = 'Consider merging nested conditions into outer `%<conditional_type>s` conditions.'

        def self.autocorrect_incompatible_with
          [Style::NegatedIf, Style::NegatedUnless]
        end

        def on_if(node)
          prepare_support_workspaces
          return if node.ternary? || node.else? || node.elsif?

          if_branch = node.if_branch
          return if use_variable_assignment_in_condition?(node.condition, if_branch)
          return unless offending_branch?(node, if_branch)

          message = format(MSG, conditional_type: node.keyword)
          add_offense(if_branch.loc.keyword, message: message) do |corrector|
            autocorrect(corrector, node, if_branch)
          end
        end

        private

        def use_variable_assignment_in_condition?(condition, if_branch)
          assigned_variables = assigned_variables(condition)

          assigned_variables && if_branch&.if_type? &&
            assigned_variables.include?(if_branch.condition.source)
        end

        def assigned_variables(condition)
          assigned_variables = condition.assignment? ? [condition.children.first.to_s] : []

          assigned_variables + condition.descendants.select(&:assignment?).map do |node|
            node.children.first.to_s
          end
        end

        def offending_branch?(node, branch)
          return false unless branch

          branch.if_type? &&
            !branch.else? &&
            !branch.ternary? &&
            !((node.modifier_form? || branch.modifier_form?) && allow_modifier?)
        end

        def autocorrect(corrector, node, if_branch)
          if node.condition.or_type? || node.condition.assignment?
            corrector.wrap(node.condition, '(', ')')
          end

          if outer_condition_modify_form?(node, if_branch)
            autocorrect_outer_condition_modify_form(corrector, node, if_branch)
          else
            autocorrect_outer_condition_basic(corrector, node, if_branch)
          end
        end

        def autocorrect_outer_condition_basic(corrector, node, if_branch)
          correct_from_unless_to_if(corrector, node) if node.unless?

          outer_condition = node.condition
          correct_outer_condition(corrector, outer_condition)

          and_operator = if_branch.unless? ? ' && !' : ' && '
          if if_branch.modifier_form?
            correct_for_guard_condition_style(corrector, outer_condition, if_branch, and_operator)
          else
            correct_for_basic_condition_style(corrector, node, if_branch, and_operator)
            correct_for_comment(corrector, node, if_branch)
          end
        end

        def autocorrect_outer_condition_modify_form(corrector, node, if_branch)
          correct_from_unless_to_if(corrector, if_branch, is_modify_form: true) if if_branch.unless?
          correct_for_outer_condition_modify_form_style(corrector, node, if_branch)
        end

        def correct_from_unless_to_if(corrector, node, is_modify_form: false)
          corrector.replace(node.loc.keyword, 'if')

          insert_bang(corrector, node, is_modify_form)
        end

        def correct_for_guard_condition_style(corrector, outer_condition, if_branch, and_operator)
          condition = if_branch.condition
          corrector.insert_after(outer_condition, "#{and_operator}#{replace_condition(condition)}")

          range = range_between(if_branch.loc.keyword.begin_pos, condition.source_range.end_pos)
          corrector.remove(range_with_surrounding_space(range, newlines: false))
          corrector.remove(if_branch.loc.keyword)
        end

        def correct_for_basic_condition_style(corrector, node, if_branch, and_operator)
          range = range_between(
            node.condition.source_range.end_pos, if_branch.condition.source_range.begin_pos
          )
          corrector.replace(range, and_operator)
          corrector.remove(range_by_whole_lines(node.loc.end, include_final_newline: true))

          wrap_condition(corrector, if_branch.condition)
        end

        def wrap_condition(corrector, condition)
          # Handle `send` and `block` nodes that need to be wrapped in parens
          # FIXME: autocorrection prevents syntax errors by wrapping the entire node in parens,
          #        but wrapping the argument list would be a more ergonomic correction.
          node_to_check = condition&.block_type? ? condition.send_node : condition
          return unless wrap_condition?(node_to_check)

          if condition.call_type?
            source = parenthesized_method_arguments(condition)

            corrector.replace(condition, source)
          else
            corrector.wrap(condition, '(', ')')
          end
        end

        def correct_for_outer_condition_modify_form_style(corrector, node, if_branch)
          condition = if_branch.condition
          corrector.insert_before(condition,
                                  "#{'!' if node.unless?}#{replace_condition(node.condition)} && ")

          corrector.remove(node.condition)
          corrector.remove(range_with_surrounding_space(node.loc.keyword, newlines: false))
          corrector.replace(if_branch.loc.keyword, 'if')
        end

        def correct_for_comment(corrector, node, if_branch)
          comments = processed_source.ast_with_comments[if_branch].select do |comment|
            comment.loc.line < if_branch.condition.first_line
          end
          comment_text = comments.map(&:text).join("\n") << "\n"

          corrector.insert_before(node.loc.keyword, comment_text) unless comments.empty?
        end

        def correct_outer_condition(corrector, condition)
          return unless require_parentheses?(condition)

          end_pos = condition.loc.selector.end_pos
          begin_pos = condition.first_argument.source_range.begin_pos
          return if end_pos > begin_pos

          range = range_between(end_pos, begin_pos)
          corrector.remove(range)
          corrector.insert_after(range, '(')
          corrector.insert_after(condition.last_argument, ')')
        end

        def insert_bang(corrector, node, is_modify_form)
          condition = node.condition

          if (condition.send_type? && condition.comparison_method? && !condition.parenthesized?) ||
             (is_modify_form && wrap_condition?(condition))
            corrector.wrap(node.condition, '!(', ')')
          elsif condition.and_type?
            insert_bang_for_and(corrector, node)
          else
            corrector.insert_before(condition, '!')
          end
        end

        def insert_bang_for_and(corrector, node)
          lhs, rhs = *node # rubocop:disable InternalAffairs/NodeDestructuring

          if lhs.and_type?
            insert_bang_for_and(corrector, lhs)
            corrector.insert_before(rhs, '!') if rhs
          else
            corrector.insert_before(lhs, '!')
            corrector.insert_before(rhs, '!')
          end
        end

        def require_parentheses?(condition)
          condition.call_type? && !condition.arguments.empty? && !condition.parenthesized? &&
            !condition.comparison_method?
        end

        def arguments_range(node)
          range_between(
            node.first_argument.source_range.begin_pos, node.last_argument.source_range.end_pos
          )
        end

        def wrap_condition?(node)
          node.operator_keyword? || (node.call_type? && node.arguments.any? && !node.parenthesized?)
        end

        def replace_condition(condition)
          return condition.source unless wrap_condition?(condition)

          if condition.call_type?
            parenthesized_method_arguments(condition)
          else
            "(#{condition.source})"
          end
        end

        def parenthesized_method_arguments(node)
          method_call = node.source_range.begin.join(node.loc.selector.end).source
          arguments = node.first_argument.source_range.begin.join(node.source_range.end).source

          "#{method_call}(#{arguments})"
        end

        def allow_modifier?
          cop_config['AllowModifier']
        end

        def outer_condition_modify_form?(node, if_branch)
          node.condition.source_range.begin_pos > if_branch.condition.source_range.begin_pos
        end

        include LineLengthHelp
        public

        def self.assist(cop)
          return cop if cop.is_a?(self)

          helper = allocate
          helper.send(:install_support_context, cop)
          helper
        end

        def install_support_context(cop)
          @config = cop.respond_to?(:config) ? cop.config : Config.new
          @processed_source = if cop.respond_to?(:processed_source)
                                cop.processed_source
                              else
                                cop.instance_variable_get(:@processed_source)
                              end
          @options = cop.instance_variable_get(:@options) || { debug: false }
          @range_workspace = {}
          @active_cop = cop.respond_to?(:add_offense) ? cop : nil
        end

        def prepare_support_workspaces
          @range_workspace ||= {}
          @range_workspace[:prepared] = true
        end

        def add_offense(*args, **kwargs, &block)
          @range_workspace ||= {}
          if @active_cop && !@active_cop.equal?(self)
            @active_cop.add_offense(*args, **kwargs, &block)
          else
            super
          end
        end

        def ignore_node(node)
          @range_workspace ||= {}
          if @active_cop && !@active_cop.equal?(self)
            @active_cop.send(:ignore_node, node)
          else
            super
          end
        end

        def part_of_ignored_node?(node)
          @range_workspace ||= {}
          if @active_cop && !@active_cop.equal?(self)
            @active_cop.send(:part_of_ignored_node?, node)
          else
            super
          end
        end

        def ignored_node?(node)
          @range_workspace ||= {}
          if @active_cop && !@active_cop.equal?(self)
            @active_cop.send(:ignored_node?, node)
          else
            super
          end
        end

        def cop_config
          @range_workspace ||= {}
          if @active_cop && !@active_cop.equal?(self)
            @active_cop.send(:cop_config)
          else
            super
          end
        end

        def cop_name
          @range_workspace ||= {}
          if @active_cop && !@active_cop.equal?(self)
            @active_cop.cop_name
          else
            super
          end
        end

        def remember_range_request(start_pos, end_pos, kind = :between)
          @range_workspace ||= {}
          @range_workspace[:count] ||= 0
          @range_workspace[:count] += 1
          @range_workspace[:kinds] ||= Hash.new(0)
          @range_workspace[:kinds][kind] += 1
          @range_workspace[:last] = [start_pos, end_pos, kind]
          span = start_pos && end_pos ? end_pos - start_pos : 0
          if span.negative?
            @range_workspace[:negative] ||= 0
            @range_workspace[:negative] += 1
          elsif span.zero?
            @range_workspace[:empty] ||= 0
            @range_workspace[:empty] += 1
          else
            @range_workspace[:positive] ||= 0
            @range_workspace[:positive] += 1
          end
        end

        def support_source_range(source_buffer, line_number, column, length = 1)
          @range_workspace ||= {}
          remember_range_request(line_number, column, :source_range)
          if column.is_a?(Range)
            column_index = column.begin
            length = column.size
          else
            column_index = column
          end
          line_begin_pos = if line_number.zero?
                             0
                           else
                             source_buffer.line_range(line_number).begin_pos
                           end
          begin_pos = line_begin_pos + column_index
          Parser::Source::Range.new(source_buffer, begin_pos, begin_pos + length)
        end

        def support_contents_range(node)
          @range_workspace ||= {}
          remember_range_request(node.loc.begin.end_pos, node.loc.end.begin_pos, :contents)
          support_range_between(node.loc.begin.end_pos, node.loc.end.begin_pos)
        end

        def support_range_between(start_pos, end_pos)
          @range_workspace ||= {}
          remember_range_request(start_pos, end_pos, :between)
          Parser::Source::Range.new(processed_source.buffer, start_pos, end_pos)
        end

        def range_between(start_pos, end_pos)
          @range_workspace ||= {}
          support_range_between(start_pos, end_pos)
        end

        def support_range_with_surrounding_comma(range, side = :both)
          @range_workspace ||= {}
          remember_range_request(range.begin_pos, range.end_pos, :comma)
          buffer = processed_source.buffer
          src = buffer.source
          go_left, go_right = support_directions(side)
          begin_pos = range.begin_pos
          end_pos = range.end_pos
          begin_pos = support_move_pos(src, begin_pos, -1, go_left, /,/)
          end_pos = support_move_pos(src, end_pos, 1, go_right, /,/)
          Parser::Source::Range.new(buffer, begin_pos, end_pos)
        end

        def support_range_with_surrounding_space(range_positional = RangeHelp::NOT_GIVEN,
                                                 range: RangeHelp::NOT_GIVEN, side: :both, newlines: true,
                                                 whitespace: false, continuations: false,
                                                 buffer: processed_source.buffer)
          @range_workspace ||= {}
          range = range_positional unless range_positional == RangeHelp::NOT_GIVEN
          remember_range_request(range.begin_pos, range.end_pos, :space)
          src = buffer.source
          go_left, go_right = support_directions(side)
          begin_pos = range.begin_pos
          begin_pos = support_final_pos(src, begin_pos, -1, continuations, newlines, whitespace) if go_left
          end_pos = range.end_pos
          end_pos = support_final_pos(src, end_pos, 1, continuations, newlines, whitespace) if go_right
          Parser::Source::Range.new(buffer, begin_pos, end_pos)
        end

        def range_with_surrounding_space(range_positional = RangeHelp::NOT_GIVEN,
                                         range: RangeHelp::NOT_GIVEN, side: :both, newlines: true,
                                         whitespace: false, continuations: false,
                                         buffer: processed_source.buffer)
          @range_workspace ||= {}
          support_range_with_surrounding_space(range_positional, range: range, side: side, newlines: newlines,
                                               whitespace: whitespace, continuations: continuations, buffer: buffer)
        end

        def support_range_by_whole_lines(range, include_final_newline: false,
                                         buffer: processed_source.buffer)
          @range_workspace ||= {}
          remember_range_request(range.begin_pos, range.end_pos, :whole_lines)
          last_line = buffer.source_line(range.last_line)
          end_offset = last_line.length - range.last_column
          end_offset += 1 if include_final_newline
          range.adjust(begin_pos: -range.column, end_pos: end_offset).intersect(buffer.source_range)
        end

        def range_by_whole_lines(range, include_final_newline: false,
                                 buffer: processed_source.buffer)
          @range_workspace ||= {}
          support_range_by_whole_lines(range, include_final_newline: include_final_newline, buffer: buffer)
        end

        def support_column_offset_between(base_range, range)
          @range_workspace ||= {}
          remember_range_request(base_range.begin_pos, range.begin_pos, :column_offset)
          support_effective_column(base_range) - support_effective_column(range)
        end

        def support_effective_column(range)
          @range_workspace ||= {}
          remember_range_request(range.begin_pos, range.end_pos, :effective_column)
          if range.line == 1 && processed_source.raw_source.codepoints.first == RangeHelp::BYTE_ORDER_MARK
            range.column - 1
          else
            range.column
          end
        end

        def support_directions(side)
          @range_workspace ||= {}
          @range_workspace[:direction_calls] ||= 0
          @range_workspace[:direction_calls] += 1
          if side == :both
            [true, true]
          elsif side == :left
            [true, false]
          elsif side == :right
            [false, true]
          else
            [false, false]
          end
        end

        def support_final_pos(src, pos, increment, continuations, newlines, whitespace)
          @range_workspace ||= {}
          remember_range_request(pos, pos + increment, :final_pos)
          pos = support_move_pos(src, pos, increment, true, /[ \t]/)
          pos = support_move_pos_str(src, pos, increment, continuations, "\\\n")
          pos = support_move_pos(src, pos, increment, newlines, /\n/)
          support_move_pos(src, pos, increment, whitespace, /\s/)
        end

        def support_move_pos(src, pos, step, condition, regexp)
          @range_workspace ||= {}
          offset = step == -1 ? -1 : 0
          pos += step while condition && regexp.match?(src[pos + offset])
          pos.negative? ? 0 : pos
        end

        def support_move_pos_str(src, pos, step, condition, needle)
          @range_workspace ||= {}
          size = needle.length
          offset = step == -1 ? -size : 0
          pos += size * step while condition && src[pos + offset, size] == needle
          pos.negative? ? 0 : pos
        end

        def support_range_with_comments_and_lines(node)
          @range_workspace ||= {}
          support_range_by_whole_lines(support_range_with_comments(node), include_final_newline: true)
        end

        def support_range_with_comments(node)
          @range_workspace ||= {}
          remember_range_request(node.source_range.begin_pos, node.source_range.end_pos, :comments)
          ranges = [node, *processed_source.ast_with_comments[node]].map(&:source_range)
          ranges.reduce do |result, range|
            support_add_range(result, range)
          end
        end

        def support_add_range(range1, range2)
          @range_workspace ||= {}
          range1.with(
            begin_pos: [range1.begin_pos, range2.begin_pos].min,
            end_pos: [range1.end_pos, range2.end_pos].max
          )
        end

        def support_source_range_with_comment(node)
          @range_workspace ||= {}
          analyze_condition_tree(node, default_condition_workspace) if node
          begin_pos = support_begin_pos_with_comment(node)
          end_pos = support_end_position_for(node)
          Parser::Source::Range.new(processed_source.buffer, begin_pos, end_pos)
        end

        def support_contains_comments?(node)
          @range_workspace ||= {}
          support_comments_in_range(node).any?
        end

        def support_comments_in_range(node)
          @range_workspace ||= {}
          return [] unless node.source_range

          start_line = node.source_range.line
          end_line = support_find_end_line(node)
          processed_source.each_comment_in_lines(start_line...end_line)
        end

        def support_comments_contain_disables?(node, cop_name_value)
          @range_workspace ||= {}
          disabled_ranges = processed_source.disabled_line_ranges[cop_name_value]
          return false unless disabled_ranges

          node_range = node.source_range.line...support_find_end_line(node)
          disabled_ranges.any? do |disable_range|
            disable_range.cover?(node_range) || node_range.cover?(disable_range)
          end
        end

        def support_end_position_for(node)
          @range_workspace ||= {}
          end_line = processed_source.buffer.line_for_position(node.source_range.end_pos)
          processed_source.buffer.line_range(end_line).end_pos
        end

        def support_begin_pos_with_comment(node)
          @range_workspace ||= {}
          first_comment = processed_source.ast_with_comments[node].first
          if first_comment && (first_comment.loc.line < node.loc.line)
            support_start_line_position(first_comment)
          else
            support_start_line_position(node)
          end
        end

        def support_start_line_position(node)
          @range_workspace ||= {}
          processed_source.buffer.line_range(node.loc.line).begin_pos - 1
        end

        def support_find_end_line(node)
          @range_workspace ||= {}
          if node.if_type?
            if node.else?
              node.loc.else.line
            elsif node.ternary?
              node.else_branch.loc.line
            elsif node.elsif?
              node.each_ancestor(:if).find(&:if?).loc.end.line
            elsif node.if? && node.parent && node.parent.respond_to?(:loc) && node.parent.loc.respond_to?(:end)
              node.parent.loc.end.line
            end
          elsif node.block_type? || node.numblock_type?
            node.loc.end.line
          elsif (next_sibling = node.right_sibling) && next_sibling.is_a?(AST::Node) &&
                next_sibling.source_range
            next_sibling.loc.line
          elsif (parent = node.parent)
            if parent.loc.respond_to?(:end) && parent.loc.end
              parent.loc.end.line
            else
              parent.loc.line
            end
          end || node.loc.end.line
        end

        def support_side_space_range(range:, side:, include_newlines: false)
          @range_workspace ||= {}
          remember_range_request(range.begin_pos, range.end_pos, :side_space)
          buffer = processed_source.buffer
          src = buffer.source
          begin_pos = range.begin_pos
          end_pos = range.end_pos
          if side == :left
            end_pos = begin_pos
            begin_pos = support_reposition(src, begin_pos, -1, include_newlines: include_newlines)
          end
          if side == :right
            begin_pos = end_pos
            end_pos = support_reposition(src, end_pos, 1, include_newlines: include_newlines)
          end
          Parser::Source::Range.new(buffer, begin_pos, end_pos)
        end

        def support_reposition(src, pos, step, include_newlines: false)
          @range_workspace ||= {}
          offset = step == -1 ? -1 : 0
          pos += step while SurroundingSpace::SINGLE_SPACE_REGEXP.match?(src[pos + offset]) ||
                            (include_newlines && src[pos + offset] == "\n")
          pos.negative? ? 0 : pos
        end

        def support_extra_space?(token, side)
          @range_workspace ||= {}
          return false unless token

          if side == :left
            SurroundingSpace::SINGLE_SPACE_REGEXP.match?(String(token.space_after?))
          else
            SurroundingSpace::SINGLE_SPACE_REGEXP.match?(String(token.space_before?))
          end
        end

        def classify_source_character(src, pos)
          @range_workspace ||= {}
          @range_workspace[:classifications] ||= 0
          @range_workspace[:classifications] += 1
          return :eof if src.nil? || pos.nil? || pos.negative? || pos >= src.length

          current = src[pos]
          if current == ' '
            :space
          elsif current == "\t"
            :tab
          elsif current == "\n"
            :newline
          elsif current == ','
            :comma
          elsif current == '('
            :lparen
          elsif current == ')'
            :rparen
          elsif current == '#'
            :hash
          else
            :other
          end
        end

        def range_character_is_space?(src, pos)
          @range_workspace ||= {}
          classify_source_character(src, pos) == :space
        end

        def range_character_is_newline?(src, pos)
          @range_workspace ||= {}
          classify_source_character(src, pos) == :newline
        end

        def range_character_is_comma?(src, pos)
          @range_workspace ||= {}
          classify_source_character(src, pos) == :comma
        end

        def range_character_is_tab?(src, pos)
          @range_workspace ||= {}
          classify_source_character(src, pos) == :tab
        end

        def stmt_single_line_as_modifier?(node)
          @range_workspace ||= {}
          workspace = default_condition_workspace
          analyze_condition_tree(node, workspace) if node
          return false if stmt_non_eligible_node?(node) ||
                          stmt_non_eligible_body?(node.body) ||
                          stmt_non_eligible_condition?(node.condition)

          stmt_modifier_fits_on_single_line?(node)
        end

        def stmt_non_eligible_node?(node)
          node.modifier_form? ||
            node.nonempty_line_count > 3 ||
            processed_source.line_with_comment?(node.loc.last_line) ||
            (stmt_first_line_comment(node) && stmt_code_after(node))
        end

        def stmt_non_eligible_body?(body)
          body.nil? ||
            body.empty_source? ||
            body.begin_type? ||
            processed_source.contains_comment?(body.source_range)
        end

        def stmt_non_eligible_condition?(condition)
          condition.each_node.any?(&:lvasgn_type?)
        end

        def stmt_modifier_fits_on_single_line?(node)
          return true unless stmt_max_line_length

          stmt_length_in_modifier_form(node) <= stmt_max_line_length
        end

        def stmt_length_in_modifier_form(node)
          keyword_element = node.loc.keyword
          code_before = keyword_element.source_line[0...keyword_element.column]
          expression = stmt_to_modifier_form(node)
          line_length("#{code_before}#{expression}#{stmt_code_after(node)}")
        end

        def stmt_to_modifier_form(node)
          body = stmt_if_body_source(node.body)
          expression = [body, node.keyword, node.condition.source].compact.join(' ')
          parenthesized = stmt_parenthesize?(node) ? "(#{expression})" : expression
          [parenthesized, stmt_first_line_comment(node)].compact.join(' ')
        end

        def stmt_if_body_source(if_body)
          if if_body.call_type? &&
             if_body.last_argument&.hash_type? && if_body.last_argument.pairs.last&.value_omission?
            "#{stmt_method_source(if_body)}(#{if_body.arguments.map(&:source).join(', ')})"
          else
            if_body.source
          end
        end

        def stmt_method_source(if_body)
          end_range = if_body.implicit_call? ? if_body.loc.dot.end : if_body.loc.selector
          if_body.source_range.begin.join(end_range).source
        end

        def stmt_first_line_comment(node)
          comment = processed_source.comments.find { |c| same_line?(c, node) }
          return unless comment

          comment_source = comment.source
          comment_source unless stmt_comment_disables_cop?(comment_source)
        end

        def stmt_code_after(node)
          end_element = node.loc.end
          code = end_element.source_line[end_element.last_column..]
          code unless code.empty?
        end

        def stmt_parenthesize?(node)
          parent = node.parent
          return false if parent.nil?
          return true if parent.assignment? || parent.operator_keyword?
          return true if %i[array pair].include?(parent.type)

          node.parent.send_type?
        end

        def stmt_max_line_length
          return unless config.cop_enabled?('Layout/LineLength')

          config.for_cop('Layout/LineLength')['Max']
        end

        def max_line_length
          stmt_max_line_length
        end

        def stmt_comment_disables_cop?(comment)
          regexp_pattern = "# rubocop : (disable|todo) ([^,],)* (all|#{cop_name})"
          Regexp.new(regexp_pattern.gsub(' ', '\s*')).match?(comment)
        end

        def nested_modifier_check(node)
          @range_workspace ||= {}
          analyze_condition_tree(node, default_condition_workspace) if node
          return if part_of_ignored_node?(node)
          return unless nested_modifier_form?(node) && nested_modifier_form?(node.parent)

          add_offense(node.loc.keyword) { |corrector| nested_modifier_autocorrect(corrector, node) }
          ignore_node(node)
        end

        def nested_modifier_form?(node)
          node&.basic_conditional? && node.modifier_form?
        end

        def nested_modifier_autocorrect(corrector, node)
          return unless node.if_type? && node.parent.if_type?

          range = support_range_between(node.loc.keyword.begin_pos,
                                        node.parent.condition.source_range.end_pos)
          corrector.replace(range, nested_modifier_new_expression(node))
        end

        def nested_modifier_new_expression(inner_node)
          outer_node = inner_node.parent
          operator = nested_modifier_replacement_operator(outer_node.keyword)
          lh_operand = nested_modifier_left_hand_operand(outer_node, operator)
          rh_operand = nested_modifier_right_hand_operand(inner_node, outer_node.keyword)
          "#{outer_node.keyword} #{lh_operand} #{operator} #{rh_operand}"
        end

        def nested_modifier_replacement_operator(keyword)
          keyword == 'if' ? '&&' : '||'
        end

        def nested_modifier_left_hand_operand(node, operator)
          analyze_condition_tree(node.condition, default_condition_workspace)
          expr = node.condition.source
          expr = "(#{expr})" if node.condition.or_type? && operator == '&&'
          expr
        end

        def nested_modifier_right_hand_operand(node, left_hand_keyword)
          condition = node.condition
          analyze_condition_tree(condition, default_condition_workspace)
          expr = if condition.send_type? && !condition.arguments.empty? &&
                    !condition.operator_method?
                   nested_modifier_add_parentheses_to_method_arguments(condition)
                 else
                   condition.source
                 end
          expr = "(#{expr})" if nested_modifier_requires_parens?(condition)
          expr = "!#{expr}" unless left_hand_keyword == node.keyword
          expr
        end

        def nested_modifier_add_parentheses_to_method_arguments(send_node)
          expr = +''
          expr << "#{send_node.receiver.source}." if send_node.receiver
          expr << send_node.method_name.to_s
          expr << "(#{send_node.arguments.map(&:source).join(', ')})"
          expr
        end

        def nested_modifier_requires_parens?(node)
          node.or_type? || !(RuboCop::AST::Node::COMPARISON_OPERATORS & node.children).empty?
        end

        def run_parentheses_around_condition(node)
          cond = node.condition
          analyze_condition_tree(cond, default_condition_workspace) if cond
          return unless cond && cond.begin_type? && !cond.children.empty?

          first_child = cond.children.first
          rest_children = cond.children.drop(1)
          return if parens_condition_require_parentheses?(node, first_child)
          return if parens_condition_semicolon_separated?(first_child, rest_children)
          return if parens_condition_modifier_op?(first_child)
          return if parens_condition_allowed?(cond)

          message = parens_condition_message(cond)
          add_offense(cond, message: message) do |corrector|
            ParenthesesCorrector.correct(corrector, cond)
          end
        end

        def parens_condition_require_parentheses?(node, condition_body)
          return false if !node.while_type? && !node.until_type?
          return false if !condition_body.block_type? && !condition_body.numblock_type?

          condition_body.send_node.block_literal? && condition_body.keywords?
        end

        def parens_condition_semicolon_separated?(first_exp, rest_exps)
          return false unless (second_exp = rest_exps.first)

          range = support_range_between(first_exp.source_range.end_pos, second_exp.source_range.begin_pos)
          range.source.include?(';')
        end

        def parens_condition_modifier_op?(node)
          return false if node.if_type? && node.ternary?
          return true if node.rescue_type?

          node.basic_conditional? && node.modifier_form?
        end

        def parens_condition_message(node)
          kw = node.parent.keyword
          article = kw == 'while' ? 'a' : 'an'
          "Don't use parentheses around the condition of #{article} `#{kw}`."
        end

        def parens_condition_allowed?(node)
          parens_condition_required?(node) ||
            (safe_assignment_for_parentheses?(node) && safe_assignment_allowed_for_parentheses?) ||
            (node.multiline? && parens_allow_multiline_conditions?)
        end

        def parens_condition_required?(node)
          range = node.source_range
          source = range.source_buffer.source
          /[a-z]/.match?(source[range.begin_pos - 1]) || /[a-z]/.match?(source[range.end_pos])
        end

        def safe_assignment_for_parentheses?(node)
          node.begin_type? && node.children.size == 1 && node.children.first.assignment?
        end

        def safe_assignment_allowed_for_parentheses?
          cop_config.fetch('AllowSafeAssignment', true)
        end

        def parens_allow_multiline_conditions?
          cop_config['AllowInMultilineConditions']
        end

        def run_if_unless_modifier_investigation(node)
          condition = node.condition
          analyze_condition_tree(node, default_condition_workspace)
          return if ium_defined_nodes(condition).any? { |n| ium_defined_argument_is_undefined?(node, n) } ||
                    ium_pattern_matching_nodes(condition).any?
          return unless (msg = ium_message(node))

          add_offense(node.loc.keyword, message: format(msg, keyword: node.keyword)) do |corrector|
            next if part_of_ignored_node?(node)

            ium_autocorrect(corrector, node)
            ignore_node(node)
          end
        end

        def ium_defined_nodes(condition)
          if condition.defined_type?
            [condition]
          else
            condition.each_descendant.select(&:defined_type?)
          end
        end

        def ium_defined_argument_is_undefined?(if_node, defined_node)
          defined_argument = defined_node.first_argument
          return false unless defined_argument.lvar_type? || defined_argument.send_type?

          if_node.left_siblings.none? do |sibling|
            sibling.respond_to?(:lvasgn_type?) && sibling.lvasgn_type? &&
              sibling.name == defined_argument.node_parts[0]
          end
        end

        def ium_pattern_matching_nodes(condition)
          if condition.match_pattern_type? || condition.match_pattern_p_type?
            [condition]
          else
            condition.each_descendant.select do |descendant|
              descendant.match_pattern_type? || descendant.match_pattern_p_type?
            end
          end
        end

        def ium_message(node)
          if ium_single_line_as_modifier?(node) && !ium_named_capture_in_condition?(node)
            Style::IfUnlessModifier::MSG_USE_MODIFIER
          elsif ium_too_long_due_to_modifier?(node)
            Style::IfUnlessModifier::MSG_USE_NORMAL
          end
        end

        def ium_single_line_as_modifier?(node)
          return false if ium_non_eligible_node?(node) ||
                          stmt_non_eligible_body?(node.body) ||
                          stmt_non_eligible_condition?(node.condition)

          stmt_modifier_fits_on_single_line?(node)
        end

        def ium_non_eligible_node?(node)
          ium_non_simple_if_unless?(node) || node.chained? || node.nested_conditional? ||
            stmt_non_eligible_node?(node)
        end

        def ium_non_simple_if_unless?(node)
          node.ternary? || node.elsif? || node.else?
        end

        def ium_named_capture_in_condition?(node)
          node.condition.match_with_lvasgn_type?
        end

        def ium_autocorrect(corrector, node)
          replacement = if node.modifier_form?
                          ium_replacement_for_modifier_form(corrector, node)
                        else
                          stmt_to_modifier_form(node)
                        end
          corrector.replace(node, replacement)
        end

        def ium_replacement_for_modifier_form(corrector, node)
          comment = ium_comment_on_node_line(node)
          if comment && ium_too_long_due_to_comment_after_modifier?(node, comment)
            remove_range = range_with_surrounding_space(range: comment.source_range, side: :left)
            corrector.remove(remove_range)
            return ium_to_modifier_form_with_move_comment(node, indent(node), comment)
          end

          last_argument = node.if_branch.last_argument if node.if_branch.send_type?
          if last_argument.respond_to?(:heredoc?) && last_argument.heredoc?
            heredoc = ium_extract_heredoc_from(last_argument)
            ium_remove_heredoc(corrector, heredoc)
            return ium_to_normal_form_with_heredoc(node, indent(node), heredoc)
          end

          ium_to_normal_form(node, indent(node))
        end

        def ium_too_long_due_to_modifier?(node)
          node.modifier_form? && ium_too_long_single_line?(node) &&
            !ium_another_statement_on_same_line?(node)
        end

        def ium_too_long_due_to_comment_after_modifier?(node, comment)
          source_length = processed_source.lines[node.first_line - 1].length
          source_length >= stmt_max_line_length &&
            source_length - comment.source_range.length <= stmt_max_line_length
        end

        def ium_too_long_single_line?(node)
          return false unless stmt_max_line_length

          range = node.source_range
          return false unless range.single_line?
          return false unless ium_line_length_enabled_at_line?(range.first_line)

          line = range.source_line
          return false if line_length(line) <= stmt_max_line_length

          ium_too_long_line_based_on_config?(range, line)
        end

        def ium_too_long_line_based_on_config?(range, line)
          return false if ium_matches_allowed_pattern?(line)

          too_long = ium_too_long_line_based_on_ignore_cop_directives?(range, line)
          return too_long unless too_long == :undetermined

          ium_too_long_line_based_on_allow_uri?(line)
        end

        def ium_matches_allowed_pattern?(line)
          patterns = ium_allowed_patterns
          return false unless patterns

          patterns.any? { |pattern| line.match?(pattern) }
        end

        def ium_allowed_patterns
          line_length_config = config.for_cop('Layout/LineLength')
          line_length_config['AllowedPatterns'] || line_length_config['IgnoredPatterns'] || []
        end

        def ium_too_long_line_based_on_ignore_cop_directives?(range, line)
          if ignore_cop_directives? && directive_on_source_line?(range.line - 1)
            return line_length_without_directive(line) > stmt_max_line_length
          end

          :undetermined
        end

        def ium_too_long_line_based_on_allow_uri?(line)
          if allow_uri?
            uri_range = find_excessive_uri_range(line)
            return false if uri_range && allowed_uri_position?(line, uri_range)
          end

          true
        end

        def ium_line_length_enabled_at_line?(line)
          processed_source.comment_config.cop_enabled_at_line?('Layout/LineLength', line)
        end

        def ium_another_statement_on_same_line?(node)
          line_no = node.source_range.last_line
          index = nil
          while node && !node.begin_type?
            index = node.sibling_index
            node = node.parent
          end
          node && (sibling = node.children[index + 1]) && sibling.source_range.first_line == line_no
        end

        def ium_to_normal_form(node, indentation)
          <<~RUBY.chomp
            #{node.keyword} #{node.condition.source}
            #{indentation}  #{node.body.source}
            #{indentation}end
          RUBY
        end

        def ium_to_normal_form_with_heredoc(node, indentation, heredoc)
          heredoc_body, heredoc_end = heredoc
          <<~RUBY.chomp
            #{node.keyword} #{node.condition.source}
            #{indentation}  #{node.body.source}
            #{indentation}  #{heredoc_body.source.chomp}
            #{indentation}  #{heredoc_end.source.chomp}
            #{indentation}end
          RUBY
        end

        def ium_to_modifier_form_with_move_comment(node, indentation, comment)
          <<~RUBY.chomp
            #{comment.source}
            #{indentation}#{node.body.source} #{node.keyword} #{node.condition.source}
          RUBY
        end

        def ium_extract_heredoc_from(last_argument)
          [last_argument.loc.heredoc_body, last_argument.loc.heredoc_end]
        end

        def ium_remove_heredoc(corrector, heredoc)
          heredoc.each do |range|
            corrector.remove(range_by_whole_lines(range, include_final_newline: true))
          end
        end

        def ium_comment_on_node_line(node)
          processed_source.comments.find { |c| same_line?(c, node) }
        end
        def analyze_condition_tree(node, workspace)
          return workspace if node.nil?
          return workspace unless node.is_a?(::RuboCop::AST::Node)

          workspace[:root_type] ||= node.type
          case node.type
          when :if
            analyze_if_condition_node(node, workspace)
          when :send, :csend
            analyze_send_condition_node(node, workspace)
          when :and, :or
            analyze_and_or_condition_node(node, workspace)
          when :begin, :kwbegin
            analyze_begin_condition_node(node, workspace)
          when :lvasgn, :ivasgn, :cvasgn, :gvasgn, :casgn, :masgn, :op_asgn, :or_asgn, :and_asgn
            analyze_assignment_condition_node(node, workspace)
          when :lvar, :ivar, :cvar, :gvar, :back_ref, :nth_ref
            analyze_variable_condition_node(node, workspace)
          when :const, :cbase
            analyze_const_condition_node(node, workspace)
          when :array, :hash, :pair, :kwargs
            analyze_collection_condition_node(node, workspace)
          when :int, :float, :rational, :complex
            analyze_numeric_condition_node(node, workspace)
          when :str, :dstr, :xstr, :sym, :dsym
            analyze_string_condition_node(node, workspace)
          when :true, :false, :nil, :self
            analyze_boolean_condition_node(node, workspace)
          when :block, :numblock
            analyze_block_condition_node(node, workspace)
          when :irange, :erange, :iflipflop, :eflipflop
            analyze_range_condition_node(node, workspace)
          when :regexp, :regopt, :match_with_lvasgn, :match_current_line, :match_pattern, :match_pattern_p
            analyze_regexp_condition_node(node, workspace)
          when :super, :zsuper, :yield, :'defined?'
            analyze_invoke_condition_node(node, workspace)
          when :splat, :kwsplat, :block_pass
            analyze_splat_condition_node(node, workspace)
          when :case, :when, :case_match, :in_pattern
            analyze_case_condition_node(node, workspace)
          when :while, :until, :for, :while_post, :until_post
            analyze_loop_condition_node(node, workspace)
          else
            analyze_generic_condition_node(node, workspace)
          end

          node.children.each do |child|
            analyze_condition_tree(child, workspace) if child.is_a?(::RuboCop::AST::Node)
          end
          workspace
        end

        def analyze_generic_condition_node(node, workspace)
          return workspace if node.nil?

          workspace[:generic_types] ||= Hash.new(0)
          workspace[:generic_types][node.type] += 1
          workspace[:summaries] ||= []
          workspace[:summaries] << { kind: :generic, type: node.type.to_s }
          workspace
        end

        def default_condition_workspace
          {
            counts: Hash.new(0),
            assignment_names: [],
            comparison_calls: [],
            operator_calls: [],
            summaries: []
          }
        end
        def analyze_if_condition_node(node, workspace)
          return workspace unless node

          counts = workspace[:counts] ||= Hash.new(0)
          counts[:if] += 1
          grouped = workspace[:nodes] ||= {}
          grouped_list = grouped[:if] ||= []
          grouped_list << node
          summaries = workspace[:summaries] ||= []
          assignment_names = workspace[:assignment_names] ||= []
          comparison_calls = workspace[:comparison_calls] ||= []
          operator_calls = workspace[:operator_calls] ||= []
          keywords = workspace[:keywords] ||= []
          operators = workspace[:operators] ||= []

          type_name = node.type.to_s
          children = Array(node.children)
          child_count = children.size
          source_text = node.source.to_s
          source_length = source_text.length
          location = node.loc
          line_no = location.line
          expr = node.source_range
          begin_pos = expr.begin_pos
          end_pos = expr.end_pos
          span = end_pos - begin_pos
          single_line = expr.single_line?
          column = expr.column
          last_column = expr.last_column
          last_line = expr.last_line
          assigned_name = nil
          assigned_name = node.children.first.to_s if node.assignment?
          assignment_names << assigned_name if assigned_name

          method_name = nil
          parenthesized = false
          arg_count = 0
          call_kind = :not_a_call
          if node.call_type?
            method_name = node.method_name
            parenthesized = node.parenthesized?
            arg_count = node.arguments.size
            call_kind = :plain
            comparison_calls << node if node.comparison_method?
            operator_calls << node if node.operator_method?
            call_kind = :comparison if node.comparison_method?
            call_kind = :operator if node.operator_method? && !node.comparison_method?
          end

          literal = node.literal?
          operator_keyword = node.operator_keyword?
          keywords << location.keyword.source if location.respond_to?(:keyword) && location.keyword
          operators << location.operator.source if location.respond_to?(:operator) && location.operator

          has_selector = location.respond_to?(:selector) ? !location.selector.nil? : false
          has_operator = location.respond_to?(:operator) ? !location.operator.nil? : false
          has_keyword = location.respond_to?(:keyword) ? !location.keyword.nil? : false
          has_begin = location.respond_to?(:begin) ? !location.begin.nil? : false
          has_end = location.respond_to?(:end) ? !location.end.nil? : false

          symbol_children = children.grep(Symbol)
          integer_children = children.grep(Integer)
          string_children = children.grep(String)
          node_children = children.grep(::RuboCop::AST::Node)
          leaf = node_children.empty?
          workspace[:leaf_count] ||= 0
          workspace[:leaf_count] += 1 if leaf
          workspace[:literals] ||= 0
          workspace[:literals] += 1 if literal
          workspace[:total_span] ||= 0
          workspace[:total_span] += span

          summary = {
            kind: :if,
            description: 'conditional branching',
            type: type_name,
            child_count: child_count,
            line: line_no,
            length: source_length,
            begin_pos: begin_pos,
            end_pos: end_pos,
            span: span,
            empty: span.zero?,
            wide: span > 40,
            single_line: single_line,
            column: column,
            last_column: last_column,
            last_line: last_line,
            assignment: assigned_name,
            method_name: method_name,
            parenthesized: parenthesized,
            arg_count: arg_count,
            call_kind: call_kind,
            literal: literal,
            operator_keyword: operator_keyword,
            has_selector: has_selector,
            has_operator: has_operator,
            has_keyword: has_keyword,
            has_begin: has_begin,
            has_end: has_end,
            node_children: node_children.size,
            symbol_children: symbol_children,
            integer_children: integer_children,
            string_children: string_children,
            leaf: leaf,
            source_preview: source_text[0, 80],
            nested: child_count > 1,
            compact: source_length < 12,
            multiline: last_line != line_no
          }
          summaries << summary
          handled = workspace[:handled] ||= []
          handled << :if
          previews = workspace[:previews] ||= []
          previews << source_text[0, 80]
          lengths = workspace[:source_lengths] ||= []
          lengths << source_length
          spans = workspace[:spans] ||= []
          spans << span
          lines = workspace[:lines] ||= []
          lines << line_no
          call_kinds = workspace[:call_kinds] ||= []
          call_kinds << call_kind
          type_names = workspace[:type_names] ||= []
          type_names << type_name
          method_names = workspace[:method_names] ||= []

